namespace Scada.Api.Runtime;

public static partial class ContextualHelpCatalog
{
    private static string HelpExample(string name)
    {
        var assembly = typeof(ContextualHelpCatalog).Assembly;
        var resource = assembly.GetManifestResourceNames().Single(item => item.EndsWith($".HelpExamples.{name}.py", StringComparison.Ordinal));
        using var stream = assembly.GetManifestResourceStream(resource)!;
        using var reader = new StreamReader(stream);
        return reader.ReadToEnd().TrimEnd();
    }

    private static IEnumerable<ContextualHelpTopic> BuildScriptLearningGuides(string locale)
    {
        yield return LT(locale, "scripts.choose-scope", "scripts",
            Tx("Antes do código: escolha onde o Script executa", "Before coding: choose where the Script runs", "Antes del código: elija dónde se ejecuta el Script"),
            Tx("Server e Client Visual atendem tarefas diferentes e usam APIs diferentes.", "Server and Client Visual serve different tasks and use different APIs.", "Server y Client Visual atienden tareas distintas y usan APIs diferentes."),
            [
                LS(locale, "Comece pelo efeito desejado", "Start with the intended effect", "Empiece por el efecto deseado",
                    "Para uma regra que deve executar no servidor sem depender de uma tela aberta, escolha Server. Para reagir a um clique ou mudar a apresentação do objeto em uma tela aberta, escolha Client Visual. Escreva a intenção em uma frase, por exemplo: quando o operador apontar para este objeto, realçá-lo; ou a cada intervalo, calcular um valor a partir de TAGs declarados.",
                    "For a rule that must run on the server without an open screen, choose Server. To respond to a click or change an object's presentation on an open screen, choose Client Visual. Write the intent in one sentence, for example: highlight this object when the operator points at it; or calculate a value from declared TAGs at each interval.",
                    "Para una regla que deba ejecutarse en el servidor sin pantalla abierta, elija Server. Para responder a un clic o cambiar la presentación de un objeto abierto, elija Client Visual. Escriba la intención en una frase: resaltar este objeto al apuntarlo; o calcular un valor desde TAGs declarados en cada intervalo."),
                LS(locale, "Não misture as duas APIs", "Keep the two APIs distinct", "Distinga las dos APIs",
                    "Server oferece funções diretas como `read_tag` e `write_server_memory` e executa um subconjunto determinístico da linguagem. Client Visual importa funções de `elite_scada`, como `tag_read` e `visual_property_write`, e usa `async def`/`await` nas chamadas assíncronas. Um exemplo de um escopo não pode ser colado no outro sem adaptação. Server não altera diretamente o desenho de uma tela; pode produzir um TAG que a tela acompanha.",
                    "Server provides direct functions such as `read_tag` and `write_server_memory` and executes a deterministic language subset. Client Visual imports functions from `elite_scada`, such as `tag_read` and `visual_property_write`, and uses `async def`/`await` for asynchronous calls. An example from one scope cannot be pasted into the other without adaptation. Server does not directly change a screen drawing; it can produce a TAG that the screen follows.",
                    "Server ofrece funciones directas como `read_tag` y `write_server_memory` y ejecuta un subconjunto determinista. Client Visual importa de `elite_scada`, como `tag_read` y `visual_property_write`, y usa `async def`/`await`. No copie un ejemplo de un alcance al otro sin adaptarlo. Server no modifica directamente un dibujo; puede producir un TAG que la pantalla sigue."),
                LS(locale, "O código precisa de uma ligação", "Code needs a connection", "El código necesita una conexión",
                    "Criar uma função não faz com que ela execute. Configure um ponto de entrada: ele liga um evento ao nome exato da função, chamado handler. Declare também os TAGs e demais recursos usados como dependências. Código, evento e referências formam a configuração; confira os três antes de procurar um defeito de sintaxe.",
                    "Creating a function does not make it run. Configure an entry point: it connects an event to the exact function name, called the handler. Also declare TAGs and other resources as dependencies. Code, event and references make up the configuration; check all three before looking for a syntax defect.",
                    "Crear una función no hace que se ejecute. Configure un punto de entrada: conecta un evento al nombre exacto de función, llamado handler. Declare TAGs y otros recursos como dependencias. Código, evento y referencias forman la configuración; compruebe los tres antes de buscar un fallo de sintaxis.")
            ], "scripts.server-syntax", "scripts.triggers-dependencies", "scripts.server", "scripts.client-visual", "scripts.client-recipes");

        yield return LT(locale, "scripts.server-syntax", "scripts",
            Tx("Server Script: sintaxe explicada desde o início", "Server Script: syntax from the beginning", "Server Script: sintaxis desde el principio"),
            Tx("Aprenda a ler uma função, usar valores e escrever condições no subconjunto aceito pelo servidor.", "Learn to read a function, use values and write conditions in the server's supported subset.", "Aprenda a leer una función, usar valores y escribir condiciones en el subconjunto del servidor."),
            [
                LS(locale, "Leia este exemplo linha por linha", "Read this example line by line", "Lea este ejemplo línea por línea",
                    "`def` inicia uma função; `on_timer` é o nome que você informará no ponto de entrada. Os parênteses vazios indicam que este handler não recebe argumentos. Os dois-pontos iniciam o bloco, e as linhas com quatro espaços pertencem à função. `current` é uma variável local que recebe a leitura; o texto entre aspas é a referência do TAG. `if` só entra no bloco seguinte quando a condição é verdadeira. `None` representa ausência de valor, não zero. `round(current, 2)` arredonda a duas casas e a última chamada grava na memória do servidor declarada.",
                    "`def` starts a function; `on_timer` is the name you will enter in the entry point. Empty parentheses mean this handler has no arguments. The colon starts its block, and four-space-indented lines belong to the function. `current` is a local variable receiving the reading; quoted text is the TAG reference. `if` enters the next block only when its condition is true. `None` means no value, not zero. `round(current, 2)` rounds to two places and the last call writes to declared server memory.",
                    "`def` inicia una función; `on_timer` es el nombre del punto de entrada. Los paréntesis vacíos indican que no recibe argumentos. Los dos puntos inician el bloque; las líneas con cuatro espacios pertenecen a la función. `current` es la variable local de lectura; el texto entre comillas es la referencia TAG. `if` entra en el bloque si la condición es verdadera. `None` significa ausencia, no cero. `round(current, 2)` redondea a dos decimales y la última llamada escribe en memoria de servidor declarada.",
                    HelpExample("server-round")),
                LS(locale, "Valores, nomes e operadores", "Values, names and operators", "Valores, nombres y operadores",
                    "Use ponto em números escritos no código, como `12.5`. Texto usa aspas; `\"Running\"` é texto e `Running` seria um nome de variável. Booleanos são `True` e `False`, com maiúscula. `=` atribui um valor; `==` compara; `!=` testa diferença; `<`, `<=`, `>` e `>=` comparam números. `+`, `-`, `*` e `/` fazem cálculos. O nome de variável deve ser consistente: `current` e `Current` são nomes diferentes. Use nomes que expliquem a grandeza.",
                    "Use a dot in numeric literals, such as `12.5`. Text uses quotes; `\"Running\"` is text while `Running` would be a variable name. Booleans are capitalized `True` and `False`. `=` assigns; `==` compares; `!=` tests difference; `<`, `<=`, `>` and `>=` compare numbers. `+`, `-`, `*` and `/` calculate. Be consistent with variable names: `current` and `Current` are different names. Choose names that describe the quantity.",
                    "Use punto en números del código, como `12.5`. Texto lleva comillas; `\"Running\"` es texto y `Running` sería una variable. Booleanos: `True` y `False` con mayúscula. `=` asigna; `==` compara; `!=` comprueba diferencia; `<`, `<=`, `>` y `>=` comparan números. `+`, `-`, `*` y `/` calculan. `current` y `Current` son nombres distintos. Use nombres que expliquen la magnitud."),
                LS(locale, "Trate ausência e divisão por zero", "Handle missing values and division by zero", "Trate ausencia y división por cero",
                    "O servidor avalia todos os operandos de `and` e `or`; eles não oferecem o curto-circuito do Python comum. Para proteger uma divisão, escreva condições aninhadas como no exemplo. Primeiro confirme as duas leituras e depois o divisor. Se faltar dado, este handler preserva o último valor de memória; a aplicação deve indicar sua disponibilidade separadamente.",
                    "The server evaluates every operand of `and` and `or`; they do not provide normal Python short-circuiting. Protect division with nested conditions as shown. First check both readings, then the divisor. If data is missing, this handler preserves the last memory value; the application must indicate its availability separately.",
                    "El servidor evalúa todos los operandos de `and` y `or`; no tienen cortocircuito de Python normal. Proteja la división con condiciones anidadas. Compruebe primero ambas lecturas y después el divisor. Sin datos, el handler conserva el último valor; la aplicación debe indicar disponibilidad por separado.",
                    HelpExample("server-ratio")),
                LS(locale, "O que este interpretador aceita", "What this interpreter supports", "Qué admite este intérprete",
                    "Use funções `def`, variáveis locais, `if/elif/else`, `return`, valores escalares, listas/dicionários literais e acesso por índice, comparações e chamadas posicionais às APIs e funções permitidas. Estão disponíveis `min`, `max`, `abs`, `round`, `int`, `float`, `bool`, `str` e `len`. Não use `import`, `for`, `while`, comprehensions, classes, `try/except`, `lambda`, f-strings, atributos ou argumentos nomeados. No nível principal, declare as funções; coloque as operações dentro delas. Essa restrição é do Server, não uma descrição geral de toda a linguagem Python.",
                    "Use `def` functions, local variables, `if/elif/else`, `return`, scalar values, literal lists/dictionaries and indexing, comparisons and positional calls to permitted functions/APIs. `min`, `max`, `abs`, `round`, `int`, `float`, `bool`, `str` and `len` are available. Do not use `import`, `for`, `while`, comprehensions, classes, `try/except`, `lambda`, f-strings, attributes or keyword arguments. At the top level declare functions; put operations inside them. This is a Server restriction, not a general description of Python.",
                    "Use funciones `def`, variables locales, `if/elif/else`, `return`, valores escalares, listas/diccionarios literales e índices, comparaciones y llamadas posicionales permitidas. Dispone de `min`, `max`, `abs`, `round`, `int`, `float`, `bool`, `str` y `len`. No use `import`, `for`, `while`, comprehensions, clases, `try/except`, `lambda`, f-strings, atributos ni argumentos nombrados. Declare funciones en el nivel principal y ponga operaciones dentro. Es una restricción de Server, no de todo Python.")
            ], "scripts.choose-scope", "scripts.triggers-dependencies", "scripts.server-recipes", "scripts.server");

        yield return LT(locale, "scripts.triggers-dependencies", "scripts",
            Tx("Ligar função, evento e dependências", "Connect function, event and dependencies", "Vincular función, evento y dependencias"),
            Tx("Preencha os campos que fazem o código executar no momento certo e acessar os recursos corretos.", "Fill in the fields that make code run at the right time and access the right resources.", "Complete los campos que ejecutan el código en el momento y con los recursos correctos."),
            [
                LS(locale, "Nome e escopo do Script", "Script name and scope", "Nombre y alcance del Script",
                    "O nome de exibição ajuda a encontrar o Script. A chave o identifica no projeto; evite nomes vagos como Script1. O escopo escolhe Server ou Client Visual e define quais eventos/APIs são válidos. Habilitado permite a participação do Script na revisão executada; não substitui publicação/ativação. O nome do handler é outro campo: ele deve coincidir com a função escrita no código, incluindo maiúsculas.",
                    "The display name helps locate the Script. Its key identifies it in the project; avoid vague names such as Script1. Scope selects Server or Client Visual and determines valid events/APIs. Enabled allows it to participate in the executed revision; it does not replace publish/activate. The handler name is a different field: it must exactly match the function in the code, including case.",
                    "El nombre visible ayuda a encontrar el Script. La clave lo identifica en el proyecto; evite nombres como Script1. El alcance elige Server o Client Visual y define eventos/APIs válidos. Habilitado permite participar en la revisión ejecutada; no sustituye publicar/activar. El handler es otro campo: debe coincidir exactamente con la función del código."),
                LS(locale, "Escolha o gatilho pela necessidade", "Choose the trigger for the task", "Elija el disparador según la tarea",
                    "Initialize prepara o estado quando a instância inicia; pode ocorrer novamente em outra ativação. Dispose encerra a instância; mantenha-o curto. TagChanged reage ao TAG selecionado e não a todos os TAGs lidos pela função. Timer chama o handler no intervalo configurado: informe milissegundos, respeite o mínimo mostrado e não escreva um laço de espera. ServerRuntimeEvent exige o evento real associado e entrega seu payload ao handler. Client Visual usa objectInteraction para Click e interações de ponteiro ligadas no painel Eventos do objeto.",
                    "Initialize prepares state when an instance starts and can run again after another activation. Dispose closes the instance; keep it short. TagChanged responds to the selected TAG, not every TAG read by the function. Timer calls the handler at its configured interval: use milliseconds, respect the displayed minimum and do not write a waiting loop. ServerRuntimeEvent requires the actual associated event and passes its payload to the handler. Client Visual uses objectInteraction for Click and pointer interactions linked in the object's Events panel.",
                    "Initialize prepara estado al iniciar la instancia y puede repetirse tras otra activación. Dispose termina la instancia; manténgalo breve. TagChanged responde al TAG seleccionado, no a todos los leídos por la función. Timer llama en el intervalo configurado: use milisegundos, respete el mínimo y no escriba bucles de espera. ServerRuntimeEvent requiere el evento real y entrega su payload. Client Visual usa objectInteraction para Click e interacciones de puntero vinculadas en Eventos."),
                LS(locale, "Declare cada referência usada", "Declare each reference used", "Declare cada referencia usada",
                    "Uma dependência diz qual recurso o Script pode usar; escrever seu nome no código não a cria. Escolha o recurso no seletor e confira tipo e finalidade: TAG de processo, ServerMemoryTag, evento ou comando. Um caminho legível só funciona quando seu binding corresponde à identidade estável declarada. Para gravar memória, o destino deve ser ServerMemoryTag. Para escrita de processo, verifique gravabilidade e permissão; para comando, declare o comando específico. Use o Object Browser para inserir referências válidas.",
                    "A dependency declares which resource the Script may use; writing its name in code does not create it. Pick the resource and check its type/purpose: process TAG, ServerMemoryTag, event or command. A readable path works only when its binding matches the declared stable identity. Server memory writes require a ServerMemoryTag target. Process writing requires writability and permission; commands require the specific command dependency. Use Object Browser to insert valid references.",
                    "Una dependencia declara qué recurso puede usar el Script; escribir el nombre no la crea. Seleccione el recurso y compruebe tipo/finalidad: TAG de proceso, ServerMemoryTag, evento o comando. Una ruta legible solo funciona si su binding coincide con la identidad declarada. Escribir memoria requiere ServerMemoryTag. Escribir proceso requiere capacidad de escritura y permiso; un comando requiere su dependencia específica. Use Object Browser para insertar referencias válidas."),
                LS(locale, "Confira se a ligação está completa", "Check the complete connection", "Compruebe la conexión completa",
                    "1. Compare o nome da função com o campo Handler. 2. Confirme escopo e evento. 3. Para TagChanged, confira o TAG disparador; para Timer, intervalo; para evento de Runtime, origem e payload. 4. Revise dependências e bindings. 5. Valide e faça o teste disponível. 6. Salve e siga publicação/ativação; confira os diagnósticos da revisão em execução. Se nada acontecer, primeiro confirme o evento e a revisão, antes de modificar o cálculo.",
                    "1. Compare the function name with Handler. 2. Confirm scope and event. 3. For TagChanged check the triggering TAG; for Timer its interval; for Runtime events the source and payload. 4. Review dependencies and bindings. 5. Validate and use the available test. 6. Save and follow publish/activate; check the running revision's diagnostics. If nothing happens, first check event and revision before changing the calculation.",
                    "1. Compare función y Handler. 2. Confirme alcance y evento. 3. En TagChanged compruebe el TAG disparador; en Timer el intervalo; en eventos Runtime origen y payload. 4. Revise dependencias y bindings. 5. Valide y use la prueba disponible. 6. Guarde y siga publicación/activación; compruebe diagnósticos de la revisión ejecutada. Si no ocurre nada, verifique evento y revisión antes de cambiar el cálculo.")
            ], "scripts.engineering", "engineering.object-browser", "scripts.server-syntax", "visual.events");

        yield return LT(locale, "scripts.server-recipes", "scripts",
            Tx("Server Script: receitas com resultado explicado", "Server Script: recipes with explained results", "Server Script: recetas con resultado explicado"),
            Tx("Adapte exemplos pequenos para calcular, guardar estado e publicar uma leitura sem inventar sua qualidade.", "Adapt small examples to calculate, retain state and publish a reading without inventing its quality.", "Adapte ejemplos pequeños para calcular, conservar estado y publicar sin inventar calidad."),
            [
                LS(locale, "Exemplo: converter uma grandeza calculada", "Example: calculate a converted quantity", "Ejemplo: calcular una magnitud convertida",
                    "Considere um TAG de vazão em litros por segundo e um ServerMemoryTag de saída em m³/h. Declare ambos e use Timer ou TagChanged conforme a aplicação. Multiplicar por 3.6 faz a conversão; apenas mudar o rótulo da unidade na tela não faria isso. O exemplo só grava se houver valor e não certifica qualidade/frescor da origem.",
                    "Assume a flow TAG in liters per second and a ServerMemoryTag output in m³/h. Declare both and use Timer or TagChanged as appropriate. Multiplying by 3.6 performs the conversion; changing a screen's unit label would not. The example writes only when a value exists and does not certify source quality/freshness.",
                    "Suponga un TAG de caudal en litros por segundo y una salida ServerMemoryTag en m³/h. Declare ambos y use Timer o TagChanged. Multiplicar por 3.6 convierte; cambiar la etiqueta de unidad no lo haría. Solo escribe si hay valor y no certifica calidad/vigencia del origen.",
                    HelpExample("server-convert")),
                LS(locale, "Exemplo: dois limites para evitar oscilação", "Example: two limits to avoid oscillation", "Ejemplo: dos límites para evitar oscilación",
                    "Um estado booleano retentivo pode ligar acima de 8 e desligar abaixo de 7, permanecendo como estava entre os dois limites. Isso é histerese. Declare pressão e memória de estado e use TagChanged na pressão. Os números são demonstrativos: escolha valores compatíveis com o processo. Se precisa de um alarme com reconhecimento e histórico de estado, configure Alarm em vez de assumir que esta variável o substitui.",
                    "A retained boolean can turn on above 8 and off below 7, keeping its state between the limits. This is hysteresis. Declare pressure and state memory and use TagChanged on pressure. Numbers are illustrative: choose values appropriate to the process. If you need an alarm with acknowledgement and state history, configure Alarm rather than treating this variable as its replacement.",
                    "Un booleano retentivo puede activarse por encima de 8 y desactivarse por debajo de 7, conservando estado entre límites. Es histéresis. Declare presión y memoria y use TagChanged en presión. Los números son ilustrativos: elija límites del proceso. Si necesita alarma con reconocimiento e histórico, configure Alarm; esta variable no lo sustituye.",
                    HelpExample("server-hysteresis")),
                LS(locale, "Exemplo: amostra com qualidade conservadora", "Example: a sample with conservative quality", "Ejemplo: muestra con calidad conservadora",
                    "`read_tag` devolve só o valor no Server. Não permite deduzir a qualidade ou o timestamp de origem. Se a aplicação ainda não comprovou a confiabilidade da leitura, publicar Uncertain mantém essa limitação visível. `publish_server_memory_sample` recebe a referência, o valor e uma TagQuality suportada. O destino precisa ser ServerMemoryTag declarado.",
                    "Server `read_tag` returns only the value. It does not establish source quality or timestamp. If the application has not established reading reliability, publishing Uncertain keeps that limitation visible. `publish_server_memory_sample` receives the reference, value and a supported TagQuality. Its target must be a declared ServerMemoryTag.",
                    "`read_tag` de Server devuelve solo el valor. No establece calidad ni timestamp de origen. Si la aplicación no ha demostrado fiabilidad, publicar Uncertain mantiene visible esa limitación. `publish_server_memory_sample` recibe referencia, valor y TagQuality admitida. El destino debe ser ServerMemoryTag declarado.",
                    HelpExample("server-sample")),
                LS(locale, "O que conferir em cada receita", "What to check in each recipe", "Qué comprobar en cada receta",
                    "Faça tentativas com valor normal, limite, ausência e tipo incorreto; confira o destino gravado. Os exemplos usam referências demonstrativas que você deve substituir pelo seletor do seu projeto. Uma memória com último valor não prova que o dado continua atual. Para eventos operacionais e comandos, consulte os guias relacionados e configure as dependências correspondentes.",
                    "Try normal, boundary, missing and wrong-type values and check the written target. Examples use illustrative references that you must replace through your project's picker. Last-value memory does not prove that the data remains current. For operational events and commands, use the related guides and configure their dependencies.",
                    "Pruebe valores normales, límites, ausencia y tipos incorrectos y compruebe el destino escrito. Sustituya las referencias demostrativas mediante el selector del proyecto. Una memoria con último valor no prueba que siga vigente. Para eventos y comandos, consulte las guías y configure sus dependencias.")
            ], "scripts.server-syntax", "scripts.server", "sources.internal-memory", "operational-events.overview", "scripts.commands-feedback");

        yield return LT(locale, "scripts.commands-feedback", "scripts",
            Tx("Escritas e comandos: parâmetros, permissão e retorno", "Writes and commands: parameters, permission and feedback", "Escrituras y comandos: parámetros, permiso y resultado"),
            Tx("Diferencie pedir um valor, solicitar um comando e confirmar o que aconteceu no equipamento.", "Distinguish writing a value, requesting a command and confirming what happened in the equipment.", "Distinga escribir un valor, solicitar un comando y confirmar qué ocurrió en el equipo."),
            [
                LS(locale, "Escolha a operação certa", "Choose the right operation", "Elija la operación adecuada",
                    "`write_tag(referência, valor)` grava um valor compatível em um TAG declarado e gravável. Uma chamada Rich Command solicita uma operação com parâmetros definidos pelo seu schema. ProcessValueWrite autoriza escrita de valor; CommandExecute autoriza comando. Uma permissão não substitui a outra, e uma sessão View Only continua restritiva. Declare a dependência e confirme destino e unidade antes de permitir ação real.",
                    "`write_tag(reference, value)` writes a compatible value to a declared writable TAG. A Rich Command call requests an operation with parameters defined by its schema. ProcessValueWrite authorizes value writing; CommandExecute authorizes commands. Neither replaces the other, and View Only remains restrictive. Declare the dependency and verify target and unit before allowing a real action.",
                    "`write_tag(referencia, valor)` escribe un valor compatible en un TAG declarado y escribible. Rich Command solicita una operación con parámetros de su schema. ProcessValueWrite autoriza valores; CommandExecute comandos. Ninguno sustituye al otro y View Only sigue restrictivo. Declare dependencia y verifique destino y unidad antes de actuar."),
                LS(locale, "Parâmetros e resultado de Rich Command", "Rich Command parameters and result", "Parámetros y resultado Rich Command",
                    "A forma é `invoke_rich_command(command_id, parameters)`: o ID deve apontar para o comando declarado; parameters é um dicionário com nomes e valores escalares compatíveis. Use o exemplo completo no guia Server Script e substitua os placeholders pelo comando real. O resultado contém outcome. Rejected indica recusa; Accepted indica solicitação aceita, não conclusão física; Completed indica conclusão informada pela operação; Failed, TimedOut e Unknown exigem diagnóstico. Em Unknown, a operação pode ter ocorrido: não repita automaticamente.",
                    "The form is `invoke_rich_command(command_id, parameters)`: the ID must identify the declared command; parameters is a dictionary of compatible named scalar values. Use the complete Server Script example and replace its placeholders with your real command. The result contains outcome. Rejected means refusal; Accepted means request accepted, not physical completion; Completed is completion reported by the operation; Failed, TimedOut and Unknown need diagnosis. With Unknown, the operation may have happened: do not automatically retry.",
                    "La forma es `invoke_rich_command(command_id, parameters)`: el ID identifica el comando declarado y parameters es un diccionario de valores escalares compatibles. Use el ejemplo completo de Server Script y sustituya placeholders. El resultado contiene outcome. Rejected es rechazo; Accepted es solicitud aceptada, no conclusión física; Completed es conclusión informada; Failed, TimedOut y Unknown requieren diagnóstico. En Unknown puede haberse ejecutado: no repita automáticamente."),
                LS(locale, "Separe intenção de realimentação", "Separate intent from feedback", "Separe intención de realimentación",
                    "O botão pode indicar pedido enviado e, ainda assim, o motor continuar parado. Mostre estado de processo a partir do TAG de realimentação e apresente pedido/erro em uma indicação própria. Depois de timeout, confira esse feedback e os registros antes de outra ação. No teste do editor, chamadas bloqueadas para proteção do processo não demonstram que o comando está defeituoso; confira qual ambiente está executando.",
                    "A button can show request sent while the motor remains stopped. Show process state from a feedback TAG and display request/error separately. After a timeout, check feedback and records before another action. Editor tests may block calls to protect the process; that does not establish a command defect. Check which environment is executing.",
                    "El botón puede indicar solicitud enviada y el motor seguir parado. Muestre estado desde el TAG de realimentación e indique solicitud/error por separado. Tras timeout, compruebe feedback y registros antes de otra acción. Las pruebas del editor pueden bloquear llamadas para proteger el proceso; eso no demuestra un defecto. Compruebe el entorno ejecutado.")
            ], "scripts.server", "bindings-commands.overview", "tags.writeability", "runtime.session-classes", "visual.events");

        yield return LT(locale, "scripts.client-api", "scripts",
            Tx("Client Visual: referência das funções", "Client Visual: function reference", "Client Visual: referencia de funciones"),
            Tx("Consulte assinatura, argumentos e finalidade antes de adaptar um exemplo.", "Check signature, arguments and purpose before adapting an example.", "Consulte firma, argumentos y finalidad antes de adaptar un ejemplo."),
            [
                LS(locale, "Importar e aguardar a resposta", "Import and await the response", "Importar y esperar la respuesta",
                    "Importe apenas as funções usadas com `from elite_scada import ...`. Nas chamadas abaixo, use `await` dentro de um handler `async def`. Referências são textos que apontam para recursos reais: selecione e declare TAGs no Script. O destino visual precisa pertencer à instância atual. Os exemplos desta tabela mostram sintaxe de chamada; os guias de receitas mostram a configuração e o código completo.",
